USE dbMaster;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF OBJECT_ID('dbo.tblManufacturers','U') IS NULL
CREATE TABLE dbo.tblManufacturers(ManufacturerId INT IDENTITY PRIMARY KEY,ManufacturerCode NVARCHAR(30) NOT NULL UNIQUE,ManufacturerName NVARCHAR(150) NOT NULL,SupplierId INT NULL REFERENCES dbo.tblSuppliers(SupplierId),ContactName NVARCHAR(100) NULL,Phone NVARCHAR(150) NULL,IsActive BIT NOT NULL DEFAULT 1,Revision INT NOT NULL DEFAULT 1,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.tblManufacturerProducts','U') IS NULL
BEGIN
CREATE TABLE dbo.tblManufacturerProducts(LinkId INT IDENTITY PRIMARY KEY,ManufacturerId INT NOT NULL REFERENCES dbo.tblManufacturers(ManufacturerId),ProductId INT NOT NULL REFERENCES dbo.tblProducts(ProductId),StartDate DATE NOT NULL,EndDate DATE NULL,ManufacturerProductCode NVARCHAR(60) NULL,Note NVARCHAR(500) NULL,Status VARCHAR(12) NOT NULL DEFAULT 'DRAFT' CHECK(Status IN('DRAFT','CONFIRMED','CANCELLED')),Revision INT NOT NULL DEFAULT 1,CreatedBy NVARCHAR(100) NOT NULL,ConfirmedBy NVARCHAR(100) NULL,ConfirmedAt DATETIME2 NULL,CancelledBy NVARCHAR(100) NULL,CancelReason NVARCHAR(500) NULL,CancelledAt DATETIME2 NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),UpdatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT CK_ManufacturerProduct_Dates CHECK(EndDate IS NULL OR EndDate>=StartDate));
CREATE INDEX IX_ManufacturerProduct_Overlap ON dbo.tblManufacturerProducts(ManufacturerId,ProductId,Status,StartDate) INCLUDE(EndDate);
END;
IF OBJECT_ID('dbo.tblManufacturerProductAudit','U') IS NULL
CREATE TABLE dbo.tblManufacturerProductAudit(AuditId BIGINT IDENTITY PRIMARY KEY,EntityType VARCHAR(20) NOT NULL,EntityId INT NOT NULL,Action VARCHAR(20) NOT NULL,Actor NVARCHAR(100) NOT NULL,BeforeJson NVARCHAR(MAX) NULL,AfterJson NVARCHAR(MAX) NOT NULL,CreatedAt DATETIME2 NOT NULL DEFAULT SYSDATETIME());
COMMIT;
